using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using System.Web.Script.Serialization;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using TasiaCraft;
public static class ResizeSnapTest {
 static string root,log;static int passed;static LivePreview preview;static readonly JavaScriptSerializer json=new JavaScriptSerializer();
 static void Require(bool ok,string label){if(!ok)throw new Exception(label);passed++;File.AppendAllText(log,"PASS "+label+Environment.NewLine);}
 static void Near(double actual,double expected,string label){Require(Math.Abs(actual-expected)<.000001,label+" actual "+actual+" expected "+expected);}
 static void Same(Point a,Point b,string label){Require((a-b).Length<.000001,label);}
 static void Reject(Action action,string label){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}Require(rejected,label);}
 static void Fixture(string path,int w,int h,bool split){using(var b=new System.Drawing.Bitmap(w,h)){using(var g=System.Drawing.Graphics.FromImage(b)){g.Clear(split?System.Drawing.Color.Red:System.Drawing.Color.Lime);if(split)g.FillRectangle(System.Drawing.Brushes.Blue,w/2,0,w/2,h);}b.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
 static Border Layer(){return preview.Stage.Children.OfType<Border>().Last();}
 static Point Grip(int x,int y){preview.UpdateLayout();var box=Layer();var r=box.Clip.Bounds;return box.TransformToAncestor(preview.Stage).Transform(new Point(x==0?r.Left:x==2?r.Right:(r.Left+r.Right)/2,y==0?r.Top:y==2?r.Bottom:(r.Top+r.Bottom)/2));}
 static Rect Bounds(){var corners=new[]{Grip(0,0),Grip(2,0),Grip(0,2),Grip(2,2)};return new Rect(new Point(corners.Min(p=>p.X),corners.Min(p=>p.Y)),new Point(corners.Max(p=>p.X),corners.Max(p=>p.Y)));}
 static Project Setup(Media media,Media green,Clip c,int w,int h){var p=new Project{Width=w,Height=h};p.Media.Add(green);p.Media.Add(media);p.Clips.Add(new Clip{MediaId=green.Id,Duration=1});c.MediaId=media.Id;c.Duration=1;c.Track=1;p.Clips.Add(c);preview.SetProject(p);preview.Seek(.2);preview.UpdateLayout();return p;}
 static byte[] PreviewPixels(int w,int h){preview.UpdateLayout();var bitmap=new RenderTargetBitmap(w,h,96,96,PixelFormats.Pbgra32);bitmap.Render(preview.Stage);var pixels=new byte[w*h*4];bitmap.CopyPixels(pixels,w*4,0);return pixels;}
 static byte[] ExportPixels(Project p,string name){string video=Path.Combine(root,name+".mp4"),png=Path.Combine(root,name+".png");Engine.Render(p,video,null);Engine.Run("ffmpeg","-y -v error -ss 0.2 -i "+Engine.Quote(video)+" -frames:v 1 -threads 1 "+Engine.Quote(png));using(var b=new System.Drawing.Bitmap(png)){Require(b.Width==p.Width&&b.Height==p.Height,name+" export dimensions");var pixels=new byte[b.Width*b.Height*4];for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){var c=b.GetPixel(x,y);int n=(y*b.Width+x)*4;pixels[n]=c.B;pixels[n+1]=c.G;pixels[n+2]=c.R;pixels[n+3]=c.A;}return pixels;}}
 static void Color(byte[] p,int x,int y,int channel,string label){int n=(y*320+x)*4;Require(p[n+channel]>180&&p[n+(channel+1)%3]<75&&p[n+(channel+2)%3]<75,label);}
 static void CheckPixels(byte[] p,string label){Color(p,80,90,2,label+" red left half");Color(p,240,90,0,label+" blue right half");Color(p,318,90,0,label+" snapped edge reaches project right");}
 static bool Matches(double? guide,double first,double last){return !guide.HasValue||new[]{first,(first+last)/2,last}.Any(n=>Math.Abs(n-guide.Value)<.000001);}
 [STAThread]public static void Main(string[] args){root=args[0];Directory.CreateDirectory(root);log=Path.Combine(root,"results.txt");File.WriteAllText(log,"");var app=new Application();preview=new LivePreview();var window=new Window{Width=1000,Height=800,Content=preview,Title="TatsiaCraft isolated resize snap acceptance"};window.Loaded+=async(s,e)=>{try{
  string split=Path.Combine(root,"split.png"),background=Path.Combine(root,"green.png");Fixture(split,320,180,true);Fixture(background,320,180,false);var media=Engine.Probe(split);var green=Engine.Probe(background);
  var c=new Clip{NativeSize=true,Scale=.75,X=-40};var p=Setup(media,green,c,320,180);var projectTarget=new[]{new Rect(0,0,320,180)};var op=new CanvasResizeOperation(c,320,180,320,180,2,1,new Point(240,90));Point pointer=new Point(316,90);var raw=op.Evaluate(pointer);Near(raw.Scale,.9875,"reference disabled snapping scale");Near(raw.X,-2,"reference disabled snapping X");Near(raw.Y,0,"reference disabled snapping Y");string original=json.Serialize(c);var snap=op.EvaluateSnapped(pointer,projectTarget,12);Require(json.Serialize(c)==original,"snapping evaluates without clip mutation");Near(snap.Result.Scale,1,"reference enabled snapping scale");Near(snap.Result.X,0,"reference enabled snapping X");Near(snap.Result.Y,0,"reference enabled snapping Y");Require(snap.GuideX.HasValue,"reference right edge guide present");Near(snap.GuideX.Value,320,"reference right guide coordinate");
  var empty=op.EvaluateSnapped(pointer,new Rect[0],12);Near(empty.Result.Scale,raw.Scale,"empty targets preserve raw scale");Near(empty.Result.X,raw.X,"empty targets preserve raw X");Require(!empty.GuideX.HasValue&&!empty.GuideY.HasValue,"empty targets have no guides");var far=op.EvaluateSnapped(pointer,new[]{new Rect(10000,10000,20,20)},12);Near(far.Result.Scale,raw.Scale,"far target preserves raw scale");var tiny=op.EvaluateSnapped(pointer,projectTarget,1);Near(tiny.Result.Scale,raw.Scale,"below threshold remains raw");var zero=op.EvaluateSnapped(pointer,projectTarget,0);Near(zero.Result.Scale,raw.Scale,"zero tolerance remains raw");
  var offset=new CanvasResizeOperation(c,320,180,320,180,2,1,new Point(243,88)).EvaluateSnapped(new Point(319,88),projectTarget,12);Near(offset.Result.Scale,1,"off-center pointer snaps same scale");Near(offset.Result.X,0,"off-center pointer snaps same X");var firstTie=op.EvaluateSnapped(pointer,new[]{new Rect(0,0,318,180),new Rect(0,0,314,180)},12);Near(firstTie.Result.Scale,318.0/320,"equal-distance targets prefer first target");var reverseTie=op.EvaluateSnapped(pointer,new[]{new Rect(0,0,314,180),new Rect(0,0,318,180)},12);Near(reverseTie.Result.Scale,314.0/320,"reversed target order deterministically reverses tie");var anchorOnly=op.EvaluateSnapped(pointer,new[]{new Rect(-50,80,50,20)},12);Near(anchorOnly.Result.Scale,raw.Scale,"fixed anchor alignments do not drive resize snaps");Require(!anchorOnly.GuideX.HasValue&&!anchorOnly.GuideY.HasValue,"fixed anchor alone produces no snap guide");preview.SetSelection(c);typeof(LivePreview).GetField("resizeOperation",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(preview,op);var liveSnap=typeof(LivePreview).GetMethod("SnapResize",BindingFlags.Instance|BindingFlags.NonPublic);foreach(double zoom in new[]{.5,1.0,2.0,20.0}){preview.SetViewZoom(zoom);preview.UpdateLayout();var transform=preview.Stage.TransformToAncestor(preview);double displayScale=(transform.Transform(new Point(1,0))-transform.Transform(new Point(0,0))).Length;Point inside=new Point(320-4/displayScale,90),outside=new Point(320-8/displayScale,90);preview.SetCanvasSnapping(true);var liveInside=(CanvasResizeSnapResult)liveSnap.Invoke(preview,new object[]{inside});Near(liveInside.Result.Scale,1,"live viewport snaps within6logicalpx zoom "+zoom);var liveOutside=(CanvasResizeSnapResult)liveSnap.Invoke(preview,new object[]{outside});Near(liveOutside.Result.Scale,op.Evaluate(outside).Scale,"live viewport excludes8logicalpx zoom "+zoom);preview.SetCanvasSnapping(false);var disabled=(CanvasResizeSnapResult)liveSnap.Invoke(preview,new object[]{inside});Near(disabled.Result.Scale,op.Evaluate(inside).Scale,"live disabled snapping raw geometry zoom "+zoom);Require(!disabled.GuideX.HasValue&&!disabled.GuideY.HasValue,"live disabled snapping clears guides zoom "+zoom);}preview.SetCanvasSnapping(true);preview.SetSelection(null);preview.SetViewZoom(0);snap.Result.ApplyTo(c);preview.Refresh();await Task.Delay(30);Same(Grip(0,1),new Point(0,90),"reference opposite visible left midpoint fixed");CheckPixels(PreviewPixels(320,180),"reference preview");CheckPixels(ExportPixels(p,"snapped-resize"),"reference export");string save=Path.Combine(root,"snapped.tasia");Engine.Save(p,save);var reopened=Engine.Load(save);Near(reopened.Clips[1].Scale,1,"save/reopen snapped scale");Near(reopened.Clips[1].X,0,"save/reopen snapped X");CheckPixels(ExportPixels(reopened,"reopened-snap"),"reopened export");
  foreach(double angle in new[]{0.0,90.0,33.0})foreach(bool native in new[]{false,true})foreach(var h in new[]{new[]{0,0},new[]{1,0},new[]{2,0},new[]{0,1},new[]{2,1},new[]{0,2},new[]{1,2},new[]{2,2}}){
   int hx=h[0],hy=h[1];string label="independent angle "+angle+" native "+native+" handle "+hx+hy;c=new Clip{NativeSize=native,Scale=.7,X=17,Y=-13,Rotation=angle,CropLeft=.125,CropTop=.1,CropRight=.2,CropBottom=.15};Setup(media,green,c,800,600);Point anchor=Grip(2-hx,2-hy),drag=Grip(hx,hy);Vector diagonal=drag-anchor;Point down=drag+new Vector(3,-2);op=new CanvasResizeOperation(c,Layer().Width,Layer().Height,800,600,hx,hy,down);original=json.Serialize(c);var desired=op.Evaluate(down+diagonal*.25);desired.ApplyTo(c);preview.Refresh();Rect target=Bounds();c.Scale=.7;c.X=17;c.Y=-13;preview.Refresh();var nearPointer=down+diagonal*.24;var unsnapped=op.Evaluate(nearPointer);unsnapped.ApplyTo(c);preview.Refresh();Point rawGrip=Grip(hx,hy);c.Scale=.7;c.X=17;c.Y=-13;preview.Refresh();snap=op.EvaluateSnapped(nearPointer,new[]{target},12);Require(json.Serialize(c)==original,label+" pure snap evaluation");Near(snap.Result.Scale,.875,label+" snap matches rendered target bounds");snap.Result.ApplyTo(c);preview.Refresh();Same(Grip(2-hx,2-hy),anchor,label+" actual crop anchor remains fixed");Require((Grip(hx,hy)-rawGrip).Length<=12.000001,label+" dragged handle adjustment stays within tolerance");Rect actual=Bounds();Require(snap.GuideX.HasValue||snap.GuideY.HasValue,label+" guide present");Require(Matches(snap.GuideX,actual.Left,actual.Right)&&Matches(snap.GuideY,actual.Top,actual.Bottom),label+" guides match actual visible bounds");Require(c.CropLeft==.125&&c.CropTop==.1&&c.CropRight==.2&&c.CropBottom==.15,label+" crop unchanged");Near(c.Rotation,angle,label+" rotation unchanged");
  }
  c=new Clip{NativeSize=true,Scale=8};Setup(media,green,c,800,600);Point boundAnchor=Grip(0,1),boundDrag=Grip(2,1);op=new CanvasResizeOperation(c,320,180,800,600,2,1,boundDrag);snap=op.EvaluateSnapped(boundDrag+new Vector(100,0),new[]{new Rect(boundDrag.X+4,0,100,600)},12);Require(snap.Result.Scale<=8,"snapped upper scale limit");snap.Result.ApplyTo(c);preview.Refresh();Same(Grip(0,1),boundAnchor,"upper limit retains actual anchor");
  Reject(()=>op.EvaluateSnapped(new Point(),null,12),"null targets rejected");Reject(()=>op.EvaluateSnapped(new Point(),new[]{Rect.Empty},12),"empty target rejected");Reject(()=>op.EvaluateSnapped(new Point(),projectTarget,double.PositiveInfinity),"infinite tolerance rejected");Reject(()=>op.EvaluateSnapped(new Point(double.NaN,0),projectTarget,12),"NaN pointer rejected");Reject(()=>op.EvaluateSnapped(new Point(),projectTarget,double.NaN),"NaN tolerance rejected");Reject(()=>op.EvaluateSnapped(new Point(),projectTarget,-1),"negative tolerance rejected");Reject(()=>op.EvaluateSnapped(new Point(),new[]{new Rect(double.NaN,0,1,1)},12),"NaN target rejected");Reject(()=>op.EvaluateSnapped(new Point(),new[]{new Rect(0,0,double.PositiveInfinity,1)},12),"infinite target rejected");
  preview.Dispose();File.AppendAllText(log,"PASS total "+passed+Environment.NewLine);app.Shutdown(0);
 }catch(Exception ex){File.AppendAllText(log,"FAIL "+ex+Environment.NewLine);preview.Dispose();app.Shutdown(1);}};app.Run(window);}
}

